function applyPlayerBoardEnemyStats(g){for(const e of g.enemies){const cfg=PLAYER_BOARD_ENEMIES[e.type];if(!cfg)continue;e.hp=e.maxHp=cfg.hp;e.damage=cfg.damage}}
function resetHeroTurn(g){g.turnOrder=['warrior','healer','rogue'];g.activeTurnIndex=0;while(g.activeTurnIndex<g.turnOrder.length&&!aliveHeroes(g).some(h=>h.role===g.turnOrder[g.activeTurnIndex]))g.activeTurnIndex++;g.activeRole=g.turnOrder[g.activeTurnIndex]||null}
function advanceHeroTurn(g){if(!g.playerBoardEnabled||g.state!=='playing')return;const current=g.party.find(h=>h.role===g.activeRole);if(current?.actions>0||current?.preparationPending||current?.evasionFreeFlip)return;do g.activeTurnIndex++;while(g.activeTurnIndex<g.turnOrder.length&&!aliveHeroes(g).some(h=>h.role===g.turnOrder[g.activeTurnIndex]));if(g.activeTurnIndex<g.turnOrder.length){g.activeRole=g.turnOrder[g.activeTurnIndex];note(g,`▶ Turno ${NAMES[g.activeRole]}.`);return}prepareManualOverlordTurn(g)}
function passHeroTurn(g){const h=g.party.find(hero=>hero.role===g.activeRole);if(!h||g.state!=='playing')return false;while(normalizePreparation(h)){const index=h.hand.findIndex(preparationDiscardable);if(index<0)break;discardPreparation(g,h,index)}h.preparationPending=0;h.actions=0;h.evasionFreeFlip=false;note(g,`→ ${NAMES[h.role]} passa.`);advanceHeroTurn(g);return true}
function initializeCommandEncounter(g){g.commandDeck={draw:shuffle(COMMAND_DECK_V01),discard:[],lastDraw:[],lastChoice:null};for(const e of g.enemies){e.bleedCount=0;e.vilePoison=0;e.garrote=0;delete e.enemyHand}}
function drawCommand(g){const deck=g.commandDeck;if(!deck.draw.length){deck.draw=shuffle(deck.discard);deck.discard=[]}return deck.draw.pop()||null}
function attachBoard(g,selections={warrior:'front',healer:'front',rogue:'front'}){g.playerBoardEnabled=true;g.commandHandMax=3;g.playerBoardAudit={events:[],consistencyChecks:0,violations:[]};g.boardSelection={...selections,rogue:'front'};if(!g.party.some(h=>h.role==='rogue'))g.party.push(rogueHero());g.telemetry.classContribution.rogue=stats();g.telemetry.actionsPlayed.rogue={};g.telemetry.cardsDrawn.rogue={};g.telemetry.handAccess.rogue={observations:0,cards:0,playable:0};g.telemetry.deaths.rogue=0;g.telemetry.miniBoss.attacks.rogue=0;g.telemetry.miniBoss.aoeDamage.rogue=0;g.telemetry.rogue={flips:0,actionsSpentOnFlip:0,stanceBlocked:{backstab:0,eviscerate:0},damage:0,firstKillContributions:0,evasionPrevented:0,preparations:0,cardsDiscarded:0,daggerUses:{left:0,right:0},daggerDamage:0};g.telemetry.warriorStance={flips:0,actionsSpentOnFlip:0,stanceBlocked:{sword:0,rend:0,parry:0}};g.telemetry.priest={flips:0,actionsSpentOnFlip:0,stanceBlocked:{quick_heal:0,slow_heal:0,bandage:0,holy_fire:0,divine_strike:0},wandUses:0,wandDamage:0,staffBonusUses:0,staffBonusValue:0};g.telemetry.critical={armed:0,played:0,byHero:{warrior:0,healer:0,rogue:0},byAbility:{}};g.telemetry.revival={encounters:0,heroes:0,byHero:{warrior:0,healer:0,rogue:0}};g.telemetry.overlordCommand={deck:{attack:3,tactic:2,special:1},activations:0,cardsDrawn:0,optionsTotal:0,optionCounts:{0:0,1:0,2:0,3:0},bleedCounts:{0:0,1:0,2:0,3:0},selected:{attack:0,tactic:0,special:0},bleedLocks:0,rendApplied:0,tacticDamage:0,specialUses:0,specialDamage:0,choiceLog:[]};for(const h of g.party){const side=selections[h.role]||'front',cfg=PLAYER_BOARD_CONFIG[h.role][side],position=h.role==='warrior'?'AGGRESSIVE':h.role==='rogue'?'FRONT':'FAR',equipment=h.role==='warrior'?['SWORD','SHIELD']:h.role==='healer'?['STAFF','WAND']:['DAGGER LEFT','DAGGER RIGHT'];h.board={side,config:cfg,equipment,position:{card:position,targetId:null}};h.maxHp=cfg.maxHp;h.hp=cfg.maxHp;h.deck=[...cfg.startingDeck];h.draw=shuffle(h.deck);h.discard=[];h.hand=[];h.criticalArmed=false;h.warriorTechniqueArmed=null;h.warriorTechniqueIndex=null;h.rogueTechniqueArmed=null;h.rogueTechniqueIndex=null;h.abilities=[...cfg.abilities];h.mastery=Object.fromEntries(cfg.abilities.map(a=>[a,0]));h.levels=Object.fromEntries(cfg.abilities.map(a=>[a,1]));h.invested=h.mastery;refill(h,g);boardAudit(g,'PLAYER_BOARD_SIDE_SELECTED',{hero:h.role,side,specializationName:cfg.specializationName,placeholder:!!cfg.placeholder})}applyPlayerBoardEnemyStats(g);initializeCommandEncounter(g);resetHeroTurn(g);validateBoard(g);return g}
const attachBoardWithoutTalents=attachBoard;
attachBoard=function(...args){const g=attachBoardWithoutTalents(...args),warrior=g.party.find(h=>h.role==='warrior'),priest=g.party.find(h=>h.role==='healer'),rogue=g.party.find(h=>h.role==='rogue');ensureWarriorTalents(warrior);ensurePriestTalents(priest);ensureRogueTalents(rogue);warrior.waitingCards=[];priest.waitingCards=[];rogue.waitingCards=[];priest.divineStrikeCasting=false;rogue.evasionFreeFlip=false;warrior.canEquipTwoHanded=true;warrior.weapon={...WARRIOR_EQUIPMENT.sword};warrior.offhand={...WARRIOR_EQUIPMENT.shield};warrior.twoHanded=false;return g};
const legacyStartEncounter=startEncounter;
startEncounter=function(g){const held=g.playerBoardEnabled?g.party.map(h=>[h,[...h.hand]]):[];legacyStartEncounter(g);if(g.playerBoardEnabled){for(const [h,hand]of held){const pool=[...h.hand,...h.draw,...h.discard];for(const card of hand)pool.splice(pool.indexOf(card),1);h.hand=hand;h.draw=shuffle(pool);h.discard=[];h.criticalArmed=false;h.warriorTechniqueArmed=null;h.warriorTechniqueIndex=null;h.rogueTechniqueArmed=null;h.rogueTechniqueIndex=null;refill(h,g)}applyPlayerBoardEnemyStats(g);initializeCommandEncounter(g);resetHeroTurn(g)}};
const legacyCheckVictory=checkVictory;
checkVictory=function(g){if(g.playerBoardEnabled&&g.state==='playing'&&!aliveEnemies(g).length){if(!aliveHeroes(g).length){g.state='lost';g.telemetry.defeatCause='party_wipe';g.currentEncounter.rounds=g.round;abandon(g);note(g,'✕ Eliminazione simultanea: nessun Eroe può rianimare il gruppo.');return}const fallen=g.party.filter(h=>h.hp<=0);if(fallen.length){g.telemetry.revival.encounters++;for(const h of fallen){h.hp=h.maxHp;h.evasion=false;h.criticalArmed=false;g.telemetry.revival.heroes++;g.telemetry.revival.byHero[h.role]++;boardAudit(g,'HERO_REVIVED',{hero:h.role,hp:h.hp})}note(g,`✚ Fine incontro: ${fallen.map(h=>NAMES[h.role]).join(', ')} torna in vita a HP massimi.`)}clearPriestRoomEffects(g)}return legacyCheckVictory(g)};
function setPosition(g,h,card,targetId=null){h.board.position={card,targetId};boardAudit(g,card?'POSITION_SET':'POSITION_CLEARED',{hero:h.role,card,targetId});validateBoard(g)}
function boardInvest(g,h,a){const before=h.mastery[a]||0;if(before>=5)return false;const oldLevel=boardLevel(before),value=before+1,newLevel=boardLevel(value);h.mastery[a]=value;h.levels[a]=newLevel;boardAudit(g,'ENGINE_INVESTED',{hero:h.role,ability:a,from:before,to:value});if(newLevel>oldLevel)boardAudit(g,'ABILITY_LEVEL_UP',{hero:h.role,ability:a,from:oldLevel,to:newLevel});validateBoard(g);return true}
function ensureWarriorTalents(h){if(!h.talents)h.talents=Object.fromEntries(Object.keys(WARRIOR_TALENTS).map(id=>[id,0]));return h.talents}
function talentAvailable(h,id,rewardCard){ensureWarriorTalents(h);const t=WARRIOR_TALENTS[id],value=h.talents[id]||0,rewardAffinity=WARRIOR_CARD_AFFINITY[rewardCard]||[],talentAffinity=WARRIOR_TALENT_AFFINITY[id]||[];return rewardAffinity.some(icon=>talentAffinity.includes(icon))&&value<t.cost&&(!t.requires||h.talents[t.requires]>=WARRIOR_TALENTS[t.requires].cost)&&(!t.requiresAny||t.requiresAny.some(key=>h.talents[key]>=WARRIOR_TALENTS[key].cost))}
function investWarriorTalent(g,h,id,rewardCard){if(!talentAvailable(h,id,rewardCard))return false;const t=WARRIOR_TALENTS[id];h.talents[id]=(h.talents[id]||0)+1;if(h.talents[id]===t.cost){if(id==='parry_mastery')h.levels.parry=2;if(id==='heroic_mastery')h.levels.sword=2;if(['cleave','shield_slam','whirlwind','improved_critical'].includes(id))for(let copy=0;copy<(['cleave','shield_slam'].includes(id)?2:1);copy++)addDeckCard(h,id==='improved_critical'?'critical':id)}boardAudit(g,'TALENT_INVESTED',{hero:'warrior',talent:id,card:rewardCard,value:h.talents[id],unlocked:h.talents[id]===t.cost});note(g,`★ ${t.name}: ${h.talents[id]}/${t.cost}${h.talents[id]===t.cost?' · SBLOCCATO':''}.`);return true}
function ensurePriestTalents(h){if(!h.talents)h.talents=Object.fromEntries(Object.keys(PRIEST_TALENTS).map(id=>[id,0]));return h.talents}
function priestTalentAvailable(h,id,rewardCard){ensurePriestTalents(h);const t=PRIEST_TALENTS[id],value=h.talents[id]||0,rewardAffinity=PRIEST_CARD_AFFINITY[rewardCard]||[],talentAffinity=PRIEST_TALENT_AFFINITY[id]||[];return rewardAffinity.some(icon=>talentAffinity.includes(icon))&&value<t.cost&&(!t.requires||h.talents[t.requires]>=PRIEST_TALENTS[t.requires].cost)&&(!t.requiresAny||t.requiresAny.some(key=>h.talents[key]>=PRIEST_TALENTS[key].cost))}
function investPriestTalent(g,h,id,rewardCard){if(!priestTalentAvailable(h,id,rewardCard))return false;const t=PRIEST_TALENTS[id];h.talents[id]=(h.talents[id]||0)+1;if(h.talents[id]===t.cost){const cards=id==='holy_shield'?['holy_shield','holy_shield']:id==='holy_fire'?['holy_fire','holy_fire','holy_fire']:id==='divine_strike'?['divine_strike','divine_strike']:id==='improved_critical'?['critical']:[];cards.forEach(card=>addDeckCard(h,card))}boardAudit(g,'TALENT_INVESTED',{hero:'healer',talent:id,card:rewardCard,value:h.talents[id],unlocked:h.talents[id]===t.cost});note(g,`★ ${t.name}: ${h.talents[id]}/${t.cost}${h.talents[id]===t.cost?' · SBLOCCATO':''}.`);return true}
function ensureRogueTalents(h){if(!h.talents)h.talents=Object.fromEntries(Object.keys(ROGUE_TALENTS).map(id=>[id,0]));return h.talents}
function rogueTalentAvailable(h,id,rewardCard){ensureRogueTalents(h);const t=ROGUE_TALENTS[id],value=h.talents[id]||0,rewardAffinity=ROGUE_CARD_AFFINITY[rewardCard]||[],talentAffinity=ROGUE_TALENT_AFFINITY[id]||[];return rewardAffinity.some(icon=>talentAffinity.includes(icon))&&value<t.cost&&(!t.requires||h.talents[t.requires]>=ROGUE_TALENTS[t.requires].cost)&&(!t.requiresAny||t.requiresAny.some(key=>h.talents[key]>=ROGUE_TALENTS[key].cost))}
function investRogueTalent(g,h,id,rewardCard){if(!rogueTalentAvailable(h,id,rewardCard))return false;const t=ROGUE_TALENTS[id];h.talents[id]=(h.talents[id]||0)+1;if(h.talents[id]===t.cost){const cards=id==='mutilate'?['mutilate','mutilate']:id==='vile_poison'?['vile_poison','vile_poison']:id==='garrote'?Array(4).fill('garrote'):id==='improved_critical'?['critical']:[];cards.forEach(card=>addDeckCard(h,card))}boardAudit(g,'TALENT_INVESTED',{hero:'rogue',talent:id,card:rewardCard,value:h.talents[id],unlocked:h.talents[id]===t.cost});note(g,`★ ${t.name}: ${h.talents[id]}/${t.cost}${h.talents[id]===t.cost?' · SBLOCCATO':''}.`);return true}
function equipWarriorTwoHanded(g,h,weapon=WARRIOR_EQUIPMENT.two_handed_fixture){if(!h.canEquipTwoHanded||!weapon.twoHanded)return false;h.weapon={...weapon};h.offhand=null;h.twoHanded=true;h.board.equipment=[weapon.id];h.warriorTechniqueArmed=null;h.warriorTechniqueIndex=null;boardAudit(g,'EQUIPMENT_CHANGED',{hero:'warrior',slot:1,item:weapon.id,damage:weapon.damage,slot2Blocked:true});note(g,`⚔ Equipaggiata ${weapon.name}: ${weapon.damage} danni base · slot 2 occupato.`);return true}
function equipWarriorSwordAndShield(g,h){h.weapon={...WARRIOR_EQUIPMENT.sword};h.offhand={...WARRIOR_EQUIPMENT.shield};h.twoHanded=false;h.board.equipment=['SWORD','SHIELD'];h.warriorTechniqueArmed=null;h.warriorTechniqueIndex=null;boardAudit(g,'EQUIPMENT_CHANGED',{hero:'warrior',slot:1,item:'sword',slot2:'shield'});note(g,'⚔ Equipaggiati Sword e Shield.');return true}
function storeWaitingReward(g,h,card){h.waitingCards=h.waitingCards||[];h.waitingCards.push(card);boardAudit(g,'REWARD_STORED',{hero:'warrior',card,waiting:h.waitingCards.length});note(g,`◷ ${NAMES[card]} messa in Riserva.`)}
function waitingCardsFor(h,icon){return(h.waitingCards||[]).filter(card=>(WARRIOR_CARD_AFFINITY[card]||[]).includes(icon))}
function waitingTalentAvailable(h,id){const target=WARRIOR_TALENT_AFFINITY[id]?.[0],source=target==='sword'?'shield':'sword',synthetic=target==='sword'?'sword':'parry';return waitingCardsFor(h,source).length>=2&&talentAvailable(h,id,synthetic)}
function hasWaitingConversion(h){return Object.keys(WARRIOR_TALENTS).some(id=>waitingTalentAvailable(h,id))}
function investWaitingTalent(g,h,id){if(!waitingTalentAvailable(h,id))return false;const target=WARRIOR_TALENT_AFFINITY[id][0],source=target==='sword'?'shield':'sword',synthetic=target==='sword'?'sword':'parry';for(let used=0;used<2;used++){const index=h.waitingCards.findIndex(card=>(WARRIOR_CARD_AFFINITY[card]||[]).includes(source));h.waitingCards.splice(index,1)}const invested=investWarriorTalent(g,h,id,synthetic);if(invested){boardAudit(g,'WAITING_CONVERTED',{hero:'warrior',source,spent:2,talent:id});note(g,`↻ 2 carte ${source==='shield'?'🛡':'⚔'} dalla Riserva → ${WARRIOR_TALENTS[id].name}.`)}return invested}
function waitingPanel(h){if(!h.waitingCards?.length)return'';const icons=card=>(WARRIOR_CARD_AFFINITY[card]||[]).map(icon=>icon==='shield'?'🛡':'⚔').join(''),buttons=Object.keys(WARRIOR_TALENTS).filter(id=>waitingTalentAvailable(h,id)).map(id=>{const target=WARRIOR_TALENT_AFFINITY[id][0],source=target==='sword'?'🛡':'⚔';return`<button data-waiting-talent="${id}">Spendi 2 ${source} → ${WARRIOR_TALENTS[id].name}</button>`}).join('');return`<section class="waiting-panel"><h3>Riserva</h3><div class="waiting-cards">${h.waitingCards.map(card=>`<span>${icons(card)} ${NAMES[card]}</span>`).join('')}</div>${buttons?`<div class="reward-actions">${buttons}</div>`:'<small>Servono due carte dello stesso lato per convertirle nel lato opposto.</small>'}</section>`}
function storePriestWaitingReward(g,h,card){h.waitingCards=h.waitingCards||[];h.waitingCards.push(card);boardAudit(g,'REWARD_STORED',{hero:'healer',card,waiting:h.waitingCards.length});note(g,`◷ ${NAMES[card]} messa in Riserva.`)}
function priestWaitingCardsFor(h,icon){return(h.waitingCards||[]).filter(card=>(PRIEST_CARD_AFFINITY[card]||[]).includes(icon))}
function priestWaitingTalentAvailable(h,id){const target=PRIEST_TALENT_AFFINITY[id]?.[0],source=target==='heal'?'damage':'heal',synthetic=target==='heal'?'quick_heal':'holy_pulse';return priestWaitingCardsFor(h,source).length>=2&&priestTalentAvailable(h,id,synthetic)}
function hasPriestWaitingConversion(h){return Object.keys(PRIEST_TALENTS).some(id=>priestWaitingTalentAvailable(h,id))}
function investPriestWaitingTalent(g,h,id){if(!priestWaitingTalentAvailable(h,id))return false;const target=PRIEST_TALENT_AFFINITY[id][0],source=target==='heal'?'damage':'heal',synthetic=target==='heal'?'quick_heal':'holy_pulse';for(let used=0;used<2;used++){const index=h.waitingCards.findIndex(card=>(PRIEST_CARD_AFFINITY[card]||[]).includes(source));h.waitingCards.splice(index,1)}const invested=investPriestTalent(g,h,id,synthetic);if(invested){boardAudit(g,'WAITING_CONVERTED',{hero:'healer',source,spent:2,talent:id});note(g,`↻ 2 carte ${source==='heal'?'✚':'✦'} dalla Riserva → ${PRIEST_TALENTS[id].name}.`)}return invested}
function priestWaitingPanel(h){if(!h.waitingCards?.length)return'';const icons=card=>affinityIcons(PRIEST_CARD_AFFINITY[card]),buttons=Object.keys(PRIEST_TALENTS).filter(id=>priestWaitingTalentAvailable(h,id)).map(id=>{const target=PRIEST_TALENT_AFFINITY[id][0],source=target==='heal'?'✦':'✚';return`<button data-priest-waiting-talent="${id}">Spendi 2 ${source} → ${PRIEST_TALENTS[id].name}</button>`}).join('');return`<section class="waiting-panel"><h3>Riserva Priest</h3><div class="waiting-cards">${h.waitingCards.map(card=>`<span>${icons(card)} ${NAMES[card]}</span>`).join('')}</div>${buttons?`<div class="reward-actions">${buttons}</div>`:'<small>Servono due carte Heal o Damage per convertirle nel ramo opposto.</small>'}</section>`}
function storeRogueWaitingReward(g,h,card){h.waitingCards=h.waitingCards||[];h.waitingCards.push(card);boardAudit(g,'REWARD_STORED',{hero:'rogue',card,waiting:h.waitingCards.length});note(g,`◷ ${NAMES[card]} messa in Riserva.`)}
function rogueWaitingCardsFor(h,icon){return(h.waitingCards||[]).filter(card=>(ROGUE_CARD_AFFINITY[card]||[]).includes(icon))}
function rogueWaitingTalentAvailable(h,id){const target=ROGUE_TALENT_AFFINITY[id]?.[0],source=target==='assassination'?'subtlety':'assassination',synthetic=target==='assassination'?'eviscerate':'backstab';return rogueWaitingCardsFor(h,source).length>=2&&rogueTalentAvailable(h,id,synthetic)}
function hasRogueWaitingConversion(h){return Object.keys(ROGUE_TALENTS).some(id=>rogueWaitingTalentAvailable(h,id))}
function investRogueWaitingTalent(g,h,id){if(!rogueWaitingTalentAvailable(h,id))return false;const target=ROGUE_TALENT_AFFINITY[id][0],source=target==='assassination'?'subtlety':'assassination',synthetic=target==='assassination'?'eviscerate':'backstab';for(let used=0;used<2;used++){const index=h.waitingCards.findIndex(card=>(ROGUE_CARD_AFFINITY[card]||[]).includes(source));h.waitingCards.splice(index,1)}const invested=investRogueTalent(g,h,id,synthetic);if(invested){boardAudit(g,'WAITING_CONVERTED',{hero:'rogue',source,spent:2,talent:id});note(g,`↻ 2 carte ${source==='assassination'?'🗡':'◈'} dalla Riserva → ${ROGUE_TALENTS[id].name}.`)}return invested}
function rogueWaitingPanel(h){if(!h.waitingCards?.length)return'';const icons=card=>affinityIcons(ROGUE_CARD_AFFINITY[card]),buttons=Object.keys(ROGUE_TALENTS).filter(id=>rogueWaitingTalentAvailable(h,id)).map(id=>{const target=ROGUE_TALENT_AFFINITY[id][0],source=target==='assassination'?'◈':'🗡';return`<button data-rogue-waiting-talent="${id}">Spendi 2 ${source} → ${ROGUE_TALENTS[id].name}</button>`}).join('');return`<section class="waiting-panel"><h3>Riserva Rogue</h3><div class="waiting-cards">${h.waitingCards.map(card=>`<span>${icons(card)} ${NAMES[card]}</span>`).join('')}</div>${buttons?`<div class="reward-actions">${buttons}</div>`:'<small>Servono due carte Assassination o Subtlety per convertirle nella specializzazione opposta.</small>'}</section>`}
function affinityIcons(affinity=[]){return affinity.map(icon=>icon==='shield'?'🛡':icon==='sword'?'⚔':icon==='heal'?'✚':icon==='damage'?'✦':icon==='assassination'?'🗡':'◈').join('')}
function rogueCanPlay(h,card){const stance=h.board.position.card;return card!=='backstab'&&card!=='eviscerate'&&card!=='mutilate'||card==='backstab'&&stance==='BEHIND'||(card==='eviscerate'||card==='mutilate')&&stance==='FRONT'}
function priestCanPlay(h,card){const stance=h.board.position.card;if(card==='holy_pulse'||card==='holy_shield')return true;if(card==='slow_heal'||card==='holy_fire')return stance==='FAR';if(card==='divine_strike'||card==='bandage')return stance==='NEAR';if(card==='quick_heal')return stance==='NEAR'||h.talents?.divine_reach>=1;return true}
function warriorCanPlay(h,card){const stance=h.board.position.card;if(h.twoHanded&&(card==='parry'||card==='shield_slam'))return false;if(card==='whirlwind')return h.twoHanded&&stance==='AGGRESSIVE';return['sword','cleave'].includes(card)?stance==='AGGRESSIVE':['parry','shield_slam'].includes(card)?stance==='DEFENSIVE':true}
function flipWarrior(g,h){if(g.state!=='playing'||h.actions<1)return false;const next=h.board.position.card==='AGGRESSIVE'?'DEFENSIVE':'AGGRESSIVE';h.actions--;h.warriorTechniqueArmed=null;h.warriorTechniqueIndex=null;g.telemetry.warriorStance.flips++;g.telemetry.warriorStance.actionsSpentOnFlip++;setPosition(g,h,next);note(g,`↔ Warrior passa in ${next} (1 azione).`);return true}
function flipRogue(g,h){const free=!!h.evasionFreeFlip;if(g.state!=='playing'||!free&&h.actions<1||h.preparationPending)return false;const next=h.board.position.card==='FRONT'?'BEHIND':'FRONT';if(free)h.evasionFreeFlip=false;else{h.actions--;g.telemetry.rogue.actionsSpentOnFlip++}h.rogueTechniqueArmed=null;h.rogueTechniqueIndex=null;g.telemetry.rogue.flips++;setPosition(g,h,next);note(g,`↔ Rogue passa in ${next} (${free?'gratis con Evasion Tricky':'1 azione'}).`);return true}
function flipPriest(g,h){if(g.state!=='playing'||h.actions<1)return false;const next=h.board.position.card==='FAR'?'NEAR':'FAR';h.actions--;g.telemetry.priest.flips++;g.telemetry.priest.actionsSpentOnFlip++;setPosition(g,h,next);note(g,`↔ Priest passa in ${next} (1 azione).`);return true}
function toggleWarriorTechnique(g,h,card,index){if(!['sword','rend','parry','cleave','shield_slam','whirlwind'].includes(card)||h.hand[index]!==card||!warriorCanPlay(h,card)||g.state!=='playing')return false;const same=h.warriorTechniqueArmed===card&&h.warriorTechniqueIndex===index;h.warriorTechniqueArmed=same?null:card;h.warriorTechniqueIndex=same?null:index;const shield=['parry','shield_slam'].includes(card);note(g,h.warriorTechniqueArmed?`◇ ${NAMES[card]} agganciata a ${shield?'Shield':'Weapon'} (0 azioni).`:`○ ${NAMES[card]} rimessa in mano.`);return true}
function consumeWarriorTechnique(g,h,card){const selected=h.warriorTechniqueIndex,index=h.hand[selected]===card?selected:h.hand.indexOf(card);if(index<0)return false;h.hand.splice(index,1);h.discard.push(card);h.warriorTechniqueArmed=null;h.warriorTechniqueIndex=null;g.telemetry.actionsPlayed.warrior[card]=(g.telemetry.actionsPlayed.warrior[card]||0)+1;boardAudit(g,'TECHNIQUE_ATTACHED',{hero:'warrior',equipment:['parry','shield_slam'].includes(card)?'SHIELD':'WEAPON',technique:card});return true}
function useSword(g,h,targetValue){if(g.state!=='playing'||h.actions<1)return false;const target=targetOf(g,targetValue);if(!aliveEnemies(g).includes(target))return false;const technique=['sword','rend','cleave','whirlwind'].includes(h.warriorTechniqueArmed)?h.warriorTechniqueArmed:null,critical=h.criticalArmed&&h.hand.includes('critical'),base=h.weapon?.damage||1;if(technique==='whirlwind'&&(!h.weapon?.twoHanded||h.actions<3))return false;h.actions-=technique==='whirlwind'?3:1;let power=base;if(technique==='sword')power+=h.talents.heroic_mastery>=2?2:1;if(technique==='rend')power+=h.talents.improved_rend||0;if(critical)power++;let dealt=0;if(technique==='cleave'||technique==='whirlwind'){const aoePower=technique==='cleave'?2:base;for(const enemy of [...aliveEnemies(g)])dealt+=damage(g,'warrior',enemy,aoePower+(critical?1:0))}else dealt=damage(g,'warrior',target,power);if(technique==='rend'){target.bleedCount=Math.min(3,(target.bleedCount||0)+1);g.telemetry.rend.played++;g.telemetry.rend.inserted++;g.telemetry.overlordCommand.rendApplied++}if(technique)consumeWarriorTechnique(g,h,technique);if(critical)consumeCritical(g,h,technique||'weapon_base');g.telemetry.warriorStance.swordBaseUses=(g.telemetry.warriorStance.swordBaseUses||0)+1;g.telemetry.warriorStance.swordBaseDamage=(g.telemetry.warriorStance.swordBaseDamage||0)+dealt;boardAudit(g,'BASE_ACTION_USED',{hero:'warrior',equipment:h.weapon?.id||'sword',technique,modifier:critical?'critical':null,value:dealt,actionCost:technique==='whirlwind'?3:1});note(g,technique==='cleave'?`⚔ Cleave${critical?' + Critico':''}: ${2+(critical?1:0)} danni a tutti i nemici (1 azione).`:technique==='whirlwind'?`🌪 Whirlwind${critical?' + Critico':''}: ${base+(critical?1:0)} danni a tutti i nemici (3 azioni).`:`⚔ ${h.weapon?.name||'Sword'}${technique?` + ${NAMES[technique]}`:''}${critical?' + Critico':''}: ${dealt} danni${technique==='rend'?` · Bleed ${target.bleedCount}/3`:''} (1 azione).`);checkVictory(g);return true}
function useShield(g,h,targetValue){if(g.state!=='playing'||h.actions<1||h.twoHanded)return false;const technique=['parry','shield_slam'].includes(h.warriorTechniqueArmed)?h.warriorTechniqueArmed:null,critical=h.criticalArmed&&h.hand.includes('critical'),target=targetOf(g,targetValue);if(technique==='shield_slam'&&!aliveEnemies(g).includes(target))return false;h.actions--;let block=1,dealt=0;if(technique==='parry')block+=h.talents.parry_mastery>=2?2:1;if(critical&&technique!=='shield_slam')block++;if(technique==='shield_slam'){dealt=damage(g,'warrior',target,3+(critical?1:0));if(target.longCast||target.casting?.cardsRequired===2){target.longCast=false;target.casting=null;boardAudit(g,'LONG_CAST_INTERRUPTED',{hero:'warrior',targetId:target.id})}}h.shield+=block;if(technique)consumeWarriorTechnique(g,h,technique);if(critical)consumeCritical(g,h,technique||'shield_base');g.telemetry.warriorStance.shieldBaseUses=(g.telemetry.warriorStance.shieldBaseUses||0)+1;g.telemetry.warriorStance.shieldBaseBlock=(g.telemetry.warriorStance.shieldBaseBlock||0)+block;boardAudit(g,'BASE_ACTION_USED',{hero:'warrior',equipment:'SHIELD',technique,modifier:critical?'critical':null,value:technique==='shield_slam'?dealt:block});note(g,technique==='shield_slam'?`🛡 Shield Slam${critical?' + Critico':''}: ${dealt} danni · +1 Block (1 azione).`:`🛡 Shield${technique?' + Parry':''}${critical?' + Critico':''}: +${block} Block (totale ${h.shield}) · 1 azione.`);checkVictory(g);return true}
function toggleRogueTechnique(g,h,card,index){if(!['backstab','eviscerate'].includes(card)||h.hand[index]!==card||!rogueCanPlay(h,card)||g.state!=='playing')return false;const same=h.rogueTechniqueArmed===card&&h.rogueTechniqueIndex===index;h.rogueTechniqueArmed=same?null:card;h.rogueTechniqueIndex=same?null:index;note(g,h.rogueTechniqueArmed?`◇ ${NAMES[card]} agganciata al prossimo Dagger (0 azioni).`:`○ ${NAMES[card]} rimessa in mano.`);return true}
function consumeRogueTechnique(g,h,card){const selected=h.rogueTechniqueIndex,index=h.hand[selected]===card?selected:h.hand.indexOf(card);if(index<0)return false;h.hand.splice(index,1);h.discard.push(card);h.rogueTechniqueArmed=null;h.rogueTechniqueIndex=null;g.telemetry.actionsPlayed.rogue[card]=(g.telemetry.actionsPlayed.rogue[card]||0)+1;boardAudit(g,'TECHNIQUE_ATTACHED',{hero:'rogue',equipment:'DAGGER',technique:card});return true}
function useDagger(g,h,targetValue,hand){if(g.state!=='playing'||h.actions<1)return false;const target=targetOf(g,targetValue);if(!aliveEnemies(g).includes(target))return false;const armed=h.rogueTechniqueArmed,technique=['backstab','eviscerate'].includes(armed)&&rogueCanPlay(h,armed)?armed:null,critical=h.criticalArmed&&h.hand.includes('critical'),firstKillPending=g.currentEncounter.firstKillRound===null;h.actions--;let power=1;if(technique==='backstab')power+=2+(h.talents?.improved_backstab>=2?2:0);if(technique==='eviscerate')power+=target.hp<=target.maxHp/2?2:1;if(critical)power++;const dealt=damage(g,'rogue',target,power);if(technique)consumeRogueTechnique(g,h,technique);if(critical)consumeCritical(g,h,technique||'dagger_base');g.telemetry.rogue.daggerUses[hand]++;g.telemetry.rogue.daggerDamage+=dealt;g.telemetry.rogue.damage+=dealt;if(firstKillPending&&target.hp<=0)g.telemetry.rogue.firstKillContributions++;boardAudit(g,'BASE_ACTION_USED',{hero:'rogue',equipment:`DAGGER_${hand.toUpperCase()}`,technique,modifier:critical?'critical':null,value:dealt});note(g,`🗡 Dagger ${hand==='left'?'sinistro':'destro'}${technique?` + ${NAMES[technique]}`:''}${critical?' + Critico':''}: ${dealt} danni (1 azione).`);checkVictory(g);return true}
function clearRogueDots(g,target,reason){const rogue=g.party.find(h=>h.role==='rogue'),poison=target.vilePoison||0,garrote=target.garrote||0,total=poison+garrote;if(!rogue||!total)return 0;rogue.discard.push(...Array(poison).fill('vile_poison'),...Array(garrote).fill('garrote'));target.vilePoison=0;target.garrote=0;boardAudit(g,'ROGUE_DOTS_CLEARED',{hero:'rogue',targetId:target.id,reason,cards:total});return total}
const damageWithoutRogueDots=damage;
damage=function(g,role,target,n){const dealt=damageWithoutRogueDots(g,role,target,n);if(g.playerBoardEnabled&&target.hp<=0)clearRogueDots(g,target,'death');return dealt};
function playRogueTalentCard(g,h,card,targetValue){if(g.state!=='playing'||h.actions<1||!h.hand.includes(card)||!rogueCanPlay(h,card))return false;const target=targetOf(g,targetValue);if(!aliveEnemies(g).includes(target))return false;g.telemetry.actionsPlayed.rogue[card]=(g.telemetry.actionsPlayed.rogue[card]||0)+1;if(card==='mutilate'){const critical=h.criticalArmed&&h.hand.includes('critical'),power=ROGUE_EQUIPMENT.mainHandDamage+ROGUE_EQUIPMENT.offHandDamage+1+(h.talents?.improved_mutilate>=2?2:0)+(critical?1:0);spend(h,card);const dealt=damage(g,'rogue',target,power);if(critical)consumeCritical(g,h,'mutilate');g.telemetry.rogue.damage+=dealt;boardAudit(g,'MUTILATE_USED',{hero:'rogue',targetId:target.id,value:dealt,critical});note(g,`🗡 Mutilate${critical?' + Critico':''}: ${dealt} danni (Main Hand + Off Hand +1).`);checkVictory(g);return true}const field=card==='vile_poison'?'vilePoison':'garrote';h.hand.splice(h.hand.indexOf(card),1);h.actions--;target[field]=(target[field]||0)+1;boardAudit(g,'ROGUE_DOT_APPLIED',{hero:'rogue',targetId:target.id,dot:card,stacks:target[field]});note(g,`${card==='vile_poison'?'☠':'🩸'} ${NAMES[card]} su ${target.type==='miniBoss'?'Mini Boss':`Goblin ${target.id}`}: ${target[field]} stack.`);return true}
function tickRogueDots(g){const rogue=g.party.find(h=>h.role==='rogue');if(!rogue)return 0;let total=0;for(const target of [...aliveEnemies(g)]){const poison=target.vilePoison||0,garrote=target.garrote||0,power=poison+garrote*2;if(!power)continue;const dealt=damage(g,'rogue',target,power);total+=dealt;g.telemetry.rogue.damage+=dealt;g.telemetry.rogue.dotDamage=(g.telemetry.rogue.dotDamage||0)+dealt;boardAudit(g,'ROGUE_DOT_TICK',{hero:'rogue',targetId:target.id,poison,garrote,value:dealt});note(g,`☠ DoT su ${target.type==='miniBoss'?'Mini Boss':`Goblin ${target.id}`}: ${dealt} danni (${poison} Poison + ${garrote} Garrote).`)}if(total)checkVictory(g);return total}
function useWand(g,h,targetValue){if(g.state!=='playing'||h.actions<1||h.board.position.card!=='FAR')return false;const target=targetOf(g,targetValue);if(!aliveEnemies(g).includes(target))return false;const critical=h.criticalArmed&&h.hand.includes('critical');h.actions--;const dealt=damage(g,'healer',target,1+(critical?1:0));if(critical)consumeCritical(g,h,'wand');g.telemetry.priest.wandUses++;g.telemetry.priest.wandDamage+=dealt;note(g,`✦ Wand${critical?' + Critico':''}: ${dealt} danni a ${target.type==='miniBoss'?'Mini Boss':`Goblin ${target.id}`}.`);checkVictory(g);return true}
function preparationDiscardable(card){return card!=='wound'&&card!=='critical'}
function normalizePreparation(h){if(!h||h.role!=='rogue')return 0;h.preparationPending=Math.min(h.preparationPending||0,h.hand.filter(preparationDiscardable).length);return h.preparationPending}
function rogueDraw(h,g){if(!h.draw.length){if(!h.discard.length)return;h.draw=shuffle(h.discard);h.discard=[]}const card=h.draw.pop();h.hand.push(card);g.telemetry.cardsDrawn.rogue[card]=(g.telemetry.cardsDrawn.rogue[card]||0)+1}
function criticalCanBoost(h,card){if(h.role==='rogue')return card==='backstab'||card==='eviscerate'||card==='mutilate';if(h.role==='healer'&&!['quick_heal','slow_heal','holy_pulse'].includes(card))return false;const level=h.levels[card]||1,next=ABILITY_TEXT[card]?.[level];return h.abilities.includes(card)&&level<3&&next&&!next.startsWith('TBD')}
function toggleCritical(g,h){if(!h.hand.includes('critical')||g.state!=='playing')return false;h.criticalArmed=!h.criticalArmed;if(h.criticalArmed)g.telemetry.critical.armed++;note(g,h.criticalArmed?`✦ ${NAMES[h.role]} prepara Critico.`:`○ ${NAMES[h.role]} conserva Critico.`);return true}
function consumeCritical(g,h,card){const index=h.hand.indexOf('critical');if(index<0)return;h.hand.splice(index,1);h.discard.push('critical');h.criticalArmed=false;g.telemetry.critical.played++;g.telemetry.critical.byHero[h.role]++;g.telemetry.critical.byAbility[card]=(g.telemetry.critical.byAbility[card]||0)+1;boardAudit(g,'CRITICAL_PLAYED',{hero:h.role,ability:card})}
function applyStaffBonus(g,h,card,target,completedSlow){if(h.role!=='healer'||!h.board.equipment.includes('STAFF')||!target)return 0;let value=0;if(card==='quick_heal'||card==='slow_heal'&&completedSlow)value=heal(g,h.role,target,1,`${card}_staff`);if(value){g.telemetry.priest.staffBonusUses++;g.telemetry.priest.staffBonusValue+=value;boardAudit(g,'EQUIPMENT_BONUS_APPLIED',{hero:'healer',equipment:'STAFF',spell:card,value});note(g,`✚ Staff: +${value} al valore principale di ${NAMES[card]}.`)}return value}
function applyPriestHealingTalent(g,h,card,target,completedSlow){if(h.talents?.improved_healing<2||!target||card!=='quick_heal'&&!(card==='slow_heal'&&completedSlow))return 0;const value=heal(g,h.role,target,2,`${card}_improved_healing`);if(value){boardAudit(g,'TALENT_BONUS_APPLIED',{hero:'healer',talent:'improved_healing',spell:card,value});note(g,`✚ Improved Healing: +${value} a ${NAMES[card]}.`)}return value}
function priestSpellDamageBonus(h){return h.talents?.improved_spell_damage>=2?2:0}
function playPriestTalentCard(g,h,card,targetValue){if(g.state!=='playing'||h.actions<1||!h.hand.includes(card)||!priestCanPlay(h,card))return false;const target=targetOf(g,targetValue),index=h.hand.indexOf(card);if(card==='holy_shield'){if(!aliveHeroes(g).includes(target))return false;h.hand.splice(index,1);h.actions--;target.holyShieldCards=(target.holyShieldCards||0)+1;g.telemetry.actionsPlayed.healer.holy_shield=(g.telemetry.actionsPlayed.healer.holy_shield||0)+1;boardAudit(g,'HOLY_SHIELD_APPLIED',{hero:'healer',target:target.role,reduction:2,stacks:target.holyShieldCards});note(g,`✚ Holy Shield su ${NAMES[target.role]}: −${target.holyShieldCards*2} danni fino a fine turno Overlord.`);return true}if(card==='holy_fire'){if(!aliveEnemies(g).includes(target))return false;spend(h,card);target.holyFireDots=(target.holyFireDots||0)+1;g.telemetry.actionsPlayed.healer.holy_fire=(g.telemetry.actionsPlayed.healer.holy_fire||0)+1;if(target.holyFireDots<3){note(g,`✦ Holy Fire: ${target.type==='miniBoss'?'Mini Boss':`Goblin ${target.id}`} sale a ${target.holyFireDots}/3 Holy DoT.`);return true}target.holyFireDots=0;const critical=h.criticalArmed&&h.hand.includes('critical'),power=5+priestSpellDamageBonus(h)+(critical?1:0),dealt=damage(g,'healer',target,power);if(critical)consumeCritical(g,h,'holy_fire');boardAudit(g,'HOLY_FIRE_DETONATED',{hero:'healer',targetId:target.id,value:dealt,critical});note(g,`✦ Holy Fire esplode${critical?' + Critico':''}: ${dealt} danni.`);checkVictory(g);return true}if(card==='divine_strike'){if(!h.divineStrikeCasting){h.hand.splice(index,1);h.actions--;h.divineStrikeCasting=true;g.telemetry.actionsPlayed.healer.divine_strike=(g.telemetry.actionsPlayed.healer.divine_strike||0)+1;boardAudit(g,'LONG_CAST_STARTED',{hero:'healer',spell:'divine_strike',cardsRequired:2});note(g,'✦ Colpo Divino in caricamento: serve la seconda carta.');return true}if(!aliveEnemies(g).includes(target))return false;h.hand.splice(index,1);h.discard.push('divine_strike','divine_strike');h.actions--;h.divineStrikeCasting=false;g.telemetry.actionsPlayed.healer.divine_strike=(g.telemetry.actionsPlayed.healer.divine_strike||0)+1;const critical=h.criticalArmed&&h.hand.includes('critical'),power=2+priestSpellDamageBonus(h)+(critical?1:0),dealt=damage(g,'healer',target,power);if(critical)consumeCritical(g,h,'divine_strike');boardAudit(g,'LONG_CAST_COMPLETED',{hero:'healer',spell:'divine_strike',targetId:target.id,value:dealt,critical});note(g,`✦ Colpo Divino${critical?' + Critico':''}: ${dealt} danni.`);checkVictory(g);return true}return false}
function playHolyPulse(g,h){if(g.state!=='playing'||h.actions<1||!h.hand.includes('holy_pulse'))return false;const targets=[...aliveEnemies(g)];if(!targets.length)return false;const critical=h.criticalArmed&&h.hand.includes('critical'),power=1+priestSpellDamageBonus(h)+(critical?1:0);spend(h,'holy_pulse');g.telemetry.actionsPlayed.healer.holy_pulse=(g.telemetry.actionsPlayed.healer.holy_pulse||0)+1;const dealt=targets.reduce((total,target)=>total+damage(g,'healer',target,power),0);if(critical)consumeCritical(g,h,'holy_pulse');boardAudit(g,'HOLY_PULSE_USED',{hero:'healer',targets:targets.map(target=>target.id),valuePerTarget:power,totalValue:dealt,critical});note(g,`✦ Impulso Sacro${critical?' + Critico':''}: ${power} ${power===1?'danno':'danni'} a tutti i nemici.`);checkVictory(g);return true}
const legacyPlay=play;
play=function(g,h,card,targetValue){
  if(g.playerBoardEnabled&&card==='critical')return toggleCritical(g,h);
  if(g.playerBoardEnabled&&h.role==='healer'&&card==='holy_pulse')return playHolyPulse(g,h);
  if(g.playerBoardEnabled&&h.role==='healer'&&['holy_shield','holy_fire','divine_strike'].includes(card))return playPriestTalentCard(g,h,card,targetValue);
  if(g.playerBoardEnabled&&h.role==='rogue'&&['mutilate','vile_poison','garrote'].includes(card))return playRogueTalentCard(g,h,card,targetValue);
  const boosted=g.playerBoardEnabled&&h.criticalArmed&&criticalCanBoost(h,card)&&!(card==='slow_heal'&&!h.casting);
  if(g.playerBoardEnabled&&h.role==='warrior'&&!warriorCanPlay(h,card)){g.telemetry.warriorStance.stanceBlocked[card]++;note(g,`⛔ ${NAMES[card]} non è disponibile in ${h.board.position.card}.`);return false}
  if(g.playerBoardEnabled&&h.role==='warrior'&&card==='rend'){if(g.state!=='playing'||h.actions<=0||!h.hand.includes(card))return false;const target=targetOf(g,targetValue);if(!aliveEnemies(g).includes(target))return false;target.bleedCount=Math.min(3,(target.bleedCount||0)+1);g.telemetry.actionsPlayed.warrior.rend=(g.telemetry.actionsPlayed.warrior.rend||0)+1;g.telemetry.rend.played++;g.telemetry.rend.inserted++;g.telemetry.overlordCommand.rendApplied++;spend(h,card);note(g,`🩸 Rend v0.3: ${target.type==='miniBoss'?'Mini Boss':`Goblin ${target.id}`} sale a ${target.bleedCount} Bleed (${3-target.bleedCount} Command).`);return true}
  if(g.playerBoardEnabled&&h.role==='healer'&&!priestCanPlay(h,card)){g.telemetry.priest.stanceBlocked[card]++;note(g,`⛔ ${NAMES[card]} non è disponibile in ${h.board.position.card}.`);return false}
  if(h.role!=='rogue'||!g.playerBoardEnabled){const level=h.levels[card],target=targetOf(g,targetValue),castingBefore=!!h.casting,sameTurnChannel=card==='slow_heal'&&h.casting?.startedEncounter===g.encounter&&h.casting.startedRound===g.round,directCritical=boosted&&card==='holy_pulse';if(boosted&&!directCritical)h.levels[card]=level+1;if(sameTurnChannel)h.casting.startedRound--;const played=legacyPlay(g,h,card,targetValue),completedSlow=castingBefore&&!h.casting;h.levels[card]=level;if(played&&h.role==='healer'){applyStaffBonus(g,h,card,target,completedSlow);applyPriestHealingTalent(g,h,card,target,completedSlow)}if(played&&directCritical&&target.hp>0)damage(g,h.role,target,1);if(played&&h.role==='healer'&&card==='holy_pulse'){if(target.hp>0&&priestSpellDamageBonus(h)){damage(g,h.role,target,priestSpellDamageBonus(h));note(g,'✦ Improved Spell Damage: +2 a Impulso Sacro.')}checkVictory(g)}if(played&&boosted){consumeCritical(g,h,card);note(g,directCritical?'✦ Critico: +1 danno principale a Impulso Sacro.':`✦ Critico: ${NAMES[card]} risolta temporaneamente a L${level+1}.`)}if(played&&sameTurnChannel)note(g,'✨ Cura Lenta completata con la seconda carta.');return played}
  if(g.state!=='playing'||h.actions<=0||!h.hand.includes(card)||card==='wound'||h.preparationPending)return false;
  if(!rogueCanPlay(h,card)){g.telemetry.rogue.stanceBlocked[card]++;note(g,`⛔ ${NAMES[card]} richiede ${card==='backstab'?'BEHIND':'FRONT'}.`);return false}
  const target=targetOf(g,targetValue),enemies=aliveEnemies(g);g.telemetry.actionsPlayed.rogue[card]=(g.telemetry.actionsPlayed.rogue[card]||0)+1;
  if(card==='backstab'||card==='eviscerate'){if(!enemies.includes(target))return false;const firstKillPending=g.currentEncounter.firstKillRound===null,power=(card==='backstab'?3+(h.talents?.improved_backstab>=2?2:0):target.hp<=target.maxHp/2?3:2)+(boosted?1:0),dealt=damage(g,'rogue',target,power);g.telemetry.rogue.damage+=dealt;if(firstKillPending&&target.hp<=0)g.telemetry.rogue.firstKillContributions++;note(g,`🗡 Rogue usa ${NAMES[card]}${boosted?' + Critico':''}: ${dealt} danni.`)}
  else if(card==='evasion'){h.evasion=true;if(h.talents?.evasion_tricky)h.evasionFreeFlip=true;note(g,`💨 Evasion pronta contro il prossimo Attack single-target${h.evasionFreeFlip?' · puoi cambiare Position gratis':''}.`)}
  else if(card==='preparation'){g.telemetry.rogue.preparations++;spend(h,card);rogueDraw(h,g);rogueDraw(h,g);h.preparationPending=Math.min(2,h.hand.filter(preparationDiscardable).length);note(g,h.preparationPending?`🃏 Preparation: pesca 2, poi scarta ${h.preparationPending} Ability.`:'🃏 Preparation: pesca 2; nessuna Ability da scartare.');return true}
  spend(h,card);if(boosted)consumeCritical(g,h,card);checkVictory(g);return true
};
function discardPreparation(g,h,index){normalizePreparation(h);const card=h.hand[index];if(!h.preparationPending||!card||!preparationDiscardable(card))return false;h.hand.splice(index,1);h.discard.push(card);h.preparationPending--;normalizePreparation(h);g.telemetry.rogue.cardsDiscarded++;if(!h.preparationPending)note(g,'✓ Preparation completata.');return true}

