function prepareNextOverlordActivation(g){const turn=g.overlordTurn,t=g.telemetry.overlordCommand;while(turn.index<turn.enemyIds.length){const e=g.enemies.find(enemy=>enemy.id===turn.enemyIds[turn.index]&&enemy.hp>0);if(!e){turn.index++;continue}const bleed=Math.min(3,e.bleedCount||0),count=3-bleed;t.activations++;t.bleedCounts[bleed]=(t.bleedCounts[bleed]||0)+1;t.optionCounts[count]=(t.optionCounts[count]||0)+1;t.optionsTotal+=count;if(!count){e.bleedCount=0;t.bleedLocks++;t.choiceLog.push({encounter:g.encounter+1,round:g.round,enemyId:e.id,bleed,draw:[],choice:null,bleedLock:true,manual:true});note(g,`🔒 ${e.type==='miniBoss'?'Mini Boss':`Goblin ${e.id}`} salta l’attivazione per Bleed.`);turn.index++;continue}turn.enemyId=e.id;turn.cards=Array.from({length:count},()=>drawCommand(g)).filter(Boolean);turn.forcedTargetRole=e.taunted&&aliveHeroes(g).some(h=>h.role==='warrior')?'warrior':null;turn.targetRole=turn.forcedTargetRole;t.cardsDrawn+=turn.cards.length;g.commandDeck.lastDraw=[...turn.cards];g.commandDeck.lastChoice=null;return}finishManualOverlordTurn(g)}
