function unlockGuaranteedMiniBoss(x){const s=x?.specialTiles?.miniBoss;if(s&&!s.placed&&x.roomsExplored>=x.config.maxRoomsExplored-1&&!s.unlocked){s.unlocked=true;s.available=true;s.unlockDepth=x.roomsExplored;x.threatTelemetry.miniBossUnlockDepth=x.roomsExplored;explorationEvent(x,'MINI_BOSS_UNLOCKED',{depth:x.roomsExplored,enrage:x.dungeonEnrage,guaranteedFinalRoom:true})}}
function playerBoardRoomCleared(g){const x=g.exploration,room=currentExplorationRoom(x);if(!room.playerBoardClearRecorded){room.playerBoardClearRecorded=true;room.fightersAlive=0;room.state='CLEARED';room.canExplore=true;room.rounds=g.enemies.length?g.round:0;room.firstKillRound=g.currentEncounter.firstKillRound;room.clearHeroes=heroesSnapshot(g);if(room.containsMiniBoss&&!room.miniBossTelemetryEnd){room.miniBossTelemetryEnd=miniBossCombatSnapshot(g);room.miniBossRounds=g.round}explorationEvent(x,'ROOM_CLEARED',{roomId:room.id,rounds:room.rounds,heroesState:room.clearHeroes});if(x.activeAmbush){x.activeAmbush=false;explorationEvent(x,'AMBUSH_CLEARED',{roomId:room.id})}if(x.config.threatSystem&&!room.chestsInitialized){room.chestsInitialized=true;room.unopenedTreasures=room.treasures.filter(t=>t==='UNOPENED').length;room.acquiredTreasures=[];x.threatTelemetry.treasureFound+=room.unopenedTreasures}}
  if(x.config.threatSystem){if(!room.treasureResolved&&room.unopenedTreasures){g.state='treasure';return false}room.treasureResolved=true;resolveMiniBossReward(x,room);x.threatTelemetry.enrageByDepth[room.depth-1]=x.dungeonEnrage}
  if(room.containsMiniBoss)return true;
  if(x.roomsExplored>=x.config.maxRoomsExplored){unlockGuaranteedMiniBoss(x);offerMiniBossTile(x);g.forceMiniBossPlacement=true;g.pendingExitChoice=true;g.state='exit_choice';boardAudit(g,'FINAL_MINI_BOSS_ROOM_QUEUED',{afterRoom:room.depth,nextRoom:room.depth+1});note(g,'⚠ Dieci stanze liberate: scegli l’uscita per la stanza 11 del Mini Boss.');return false}
  unlockGuaranteedMiniBoss(x);g.pendingExitChoice=true;g.state='exit_choice';boardAudit(g,'HERO_EXIT_CHOICE_OFFERED',{roomId:room.id,exits:room.exits.map(exit=>exit.id)});note(g,'🧭 Stanza liberata: gli Eroi scelgono quale uscita imboccare.');return false
}
