function choosePlayerExit(g,exitId){if(!g.playerBoardEnabled||g.state!=='exit_choice'||!g.pendingExitChoice)return false;const x=g.exploration,room=currentExplorationRoom(x),exit=room.exits.find(item=>item.id===exitId);if(!exit)return false;x.playerChosenExitId=exitId;const policy=x.config.exitPolicy;x.config.exitPolicy='RANDOM';offerMiniBossTile(x);const next=generateExplorationRoom(x);x.config.exitPolicy=policy;recordMiniBossMaterialization(x,next);g.sequence.push(next.fighters.length);g.pendingExitChoice=false;boardAudit(g,'HERO_EXIT_SELECTED',{roomId:room.id,exitId,icons:exit.icons,nextRoomId:next.id});g.encounter++;g.party.filter(h=>h.hp>0).forEach(h=>h.hp=Math.min(h.maxHp,h.hp+CONFIG.interEncounterHeal));g.pendingRewards=g.party.filter(h=>h.hp>0).map(h=>({hero:h,ability:h.abilities[Math.floor(Math.random()*h.abilities.length)]}));g.state='reward';note(g,`🧭 Uscita ${exitId} scelta. L'Overlord gioca ${roomDisplayName(x,next)}.`);note(g,'★ Scegli DECK o ENGINE per ogni ricompensa.');return true}
