const renderWithRogueTalents=render;
render=function(){
  renderWithRogueTalents();if(!game.playerBoardEnabled)return;
  const rogue=game.party.find(h=>h.role==='rogue');ensureRogueTalents(rogue);
  if(game.state==='reward'){
    const party=document.getElementById('party');
    game.pendingRewards.forEach((reward,index)=>{if(reward.hero!==rogue)return;const section=party.querySelector(`[data-reward="${index}"]`)?.closest('.reward-card');if(!section)return;section.querySelector('[data-choice="upgrade"]')?.remove();const actions=section.querySelector('.reward-actions');if(actions&&!actions.querySelector('[data-choice="waiting"]'))actions.insertAdjacentHTML('beforeend',`<button data-reward="${index}" data-choice="waiting" class="secondary">Metti in Riserva</button>`);if(!section.querySelector('.talent-page'))section.insertAdjacentHTML('beforeend',rogueTalentPage(rogue));const affinity=section.querySelector('.reward-affinity');if(affinity)affinity.innerHTML=affinityIcons(ROGUE_CARD_AFFINITY[reward.ability]);section.querySelectorAll('[data-reward]').forEach(button=>button.onclick=()=>{claimReward(game,+button.dataset.reward,button.dataset.choice);render()})});
    if(rogue.waitingCards?.length&&!party.querySelector('.rogue-waiting-panel'))party.insertAdjacentHTML('beforeend',rogueWaitingPanel(rogue).replace('class="waiting-panel"','class="waiting-panel rogue-waiting-panel"'));
    party.querySelectorAll('[data-rogue-waiting-talent]').forEach(button=>button.onclick=()=>{investRogueWaitingTalent(game,rogue,button.dataset.rogueWaitingTalent);render()});
    party.querySelectorAll('.talent-page[data-talent-role="rogue"]').forEach(page=>page.ontoggle=()=>rogue.talentsOpen=page.open);return
  }
  const column=[...document.querySelectorAll('.hero-column')].find(node=>node.querySelector('h2')?.textContent.includes(NAMES.rogue)),board=column?.querySelector('.player-board');board?.querySelector('.mastery-grid')?.remove();if(board&&!board.querySelector('.talent-page'))board.insertAdjacentHTML('beforeend',rogueTalentPage(rogue));const page=board?.querySelector('.talent-page');if(page)page.ontoggle=()=>rogue.talentsOpen=page.open;if(rogue.evasionFreeFlip){const flip=column?.querySelector('[data-flip="rogue"]');if(flip){flip.disabled=false;flip.textContent=`Flip → ${rogue.board.position.card==='FRONT'?'BEHIND':'FRONT'} · GRATIS`}const slots=board?.querySelector('.board-slots'),status=board?.querySelector('.priest-status');if(status)status.insertAdjacentHTML('beforeend','<span>💨 Evasion Tricky · Flip gratis disponibile</span>');else slots?.insertAdjacentHTML('afterend','<div class="priest-status"><span>💨 Evasion Tricky · Flip gratis disponibile</span></div>')}
};

function automaticEnemyTarget(g){const selected=targetOf(g,g.selectedTarget);if(aliveEnemies(g).includes(selected))return g.selectedTarget;const enemy=aliveEnemies(g)[0];if(enemy)g.selectedTarget=`enemy:x:${enemy.id}`;return g.selectedTarget}
function resolveWarriorTechniqueClick(g,h,index){const card=h.hand[index];if(!['sword','rend','parry','cleave','shield_slam','whirlwind'].includes(card)||!warriorCanPlay(h,card))return false;h.warriorTechniqueArmed=card;h.warriorTechniqueIndex=index;const resolved=['parry','shield_slam'].includes(card)?useShield(g,h,automaticEnemyTarget(g)):useSword(g,h,automaticEnemyTarget(g));if(!resolved){h.warriorTechniqueArmed=null;h.warriorTechniqueIndex=null}return resolved}
function resolveRogueTechniqueClick(g,h,index){const card=h.hand[index];if(!['backstab','eviscerate'].includes(card)||!rogueCanPlay(h,card))return false;h.rogueTechniqueArmed=card;h.rogueTechniqueIndex=index;const resolved=useDagger(g,h,automaticEnemyTarget(g),'left');if(!resolved){h.rogueTechniqueArmed=null;h.rogueTechniqueIndex=null}return resolved}
const renderWithImmediateTechniques=render;
render=function(){renderWithImmediateTechniques();if(!game.playerBoardEnabled||game.state!=='playing')return;document.querySelectorAll('[data-war-tech]').forEach(button=>button.onclick=()=>{const h=game.party[+button.dataset.warrior];if(resolveWarriorTechniqueClick(game,h,+button.dataset.warTech))advanceHeroTurn(game);render()});document.querySelectorAll('[data-rogue-tech]').forEach(button=>button.onclick=()=>{const h=game.party[+button.dataset.rogue];if(resolveRogueTechniqueClick(game,h,+button.dataset.rogueTech))advanceHeroTurn(game);render()})};

