const mobileTargetBar=document.createElement('aside');mobileTargetBar.className='mobile-target-bar';mobileTargetBar.setAttribute('aria-label','Nemici nella stanza');document.body.append(mobileTargetBar);
function updateMobileTargetBar(){const source=document.querySelector('#enemies .room-targets'),header=document.querySelector('.app-header'),mobile=innerWidth<=700,visible=mobile&&game.playerBoardEnabled&&game.state==='playing'&&!document.getElementById('gamePage').hidden&&source&&source.children.length&&source.getBoundingClientRect().bottom<=header.getBoundingClientRect().bottom;mobileTargetBar.classList.toggle('visible',!!visible);mobileTargetBar.setAttribute('aria-hidden',visible?'false':'true');if(header)mobileTargetBar.style.top=`${Math.ceil(header.getBoundingClientRect().bottom)}px`}
function syncMobileTargetBar(){const source=document.querySelector('#enemies .room-targets');mobileTargetBar.innerHTML=source?`<strong>Nemici nella stanza</strong><div class="room-targets">${source.innerHTML}</div>`:'';mobileTargetBar.querySelectorAll('[data-target]').forEach(button=>button.onclick=()=>{game.selectedTarget=button.dataset.target;render()});updateMobileTargetBar()}
